mapper.select:
select  from nad_media_asset
where owner_kind = #{kind} and owner_id = #{id}
order by id desc

select  from nad_media_asset
where status = 'DELETED' and deleted_at is not null and deleted_at < #{before}
order by deleted_at asc

mapper.update:
update nad_media_asset
status = #{status}, update_by = #{updateBy}, update_time = now(), superseded_by = #{supersededBy}, deleted_at = now(), deleted_by = #{deletedBy},
where id = #{id}
